function enhanceResponsiveTables(scope=root){scope.querySelectorAll('.table-wrap table').forEach(table=>{const labels=[...table.querySelectorAll('thead th')].map(th=>th.textContent.trim());table.querySelectorAll('tbody tr').forEach(row=>[...row.children].forEach((cell,i)=>{if(cell.tagName==='TD'&&!cell.hasAttribute('data-label'))cell.dataset.label=labels[i]||''}))})}
