  const wholesaleRows=wholesale.map(tx=>{const customer=customers.find(c=>c.id===tx.customer_id),items=linesFor(tx),output=items.reduce((s,l)=>s+Number(l.gst_amount||0),0),input=items.reduce((s,l)=>s+(Number(l.input_gst_amount||0)||Number(l.inventory_gst_amount||0)*Math.max(0,Number(l.quantity||0)-Number(l.returned_quantity||0))),0),cgst=output/2,sgst=output/2;return {tx,customer,output,input,cgst,sgst,net:output-input}});
