  const moneyCell=n=>`<td class="amount">${currencyWhole(n)}</td>`,wholesaleBody=wholesaleRows.map(({tx,customer,input,cgst,sgst,net})=>`<tr><td class="mono"><b>${escapeHtml(tx.reference||tx.invoice_number||'—')}</b></td><td>${tx.invoice_date?new Date(`${tx.invoice_date}T00:00:00`).toLocaleDateString(uiLocale(),{day:'numeric',month:'short',year:'numeric'}):'—'}</td><td>${escapeHtml(customer?.name||tx.customer_name||'—')}</td><td>${escapeHtml(customer?.gstin||'Not provided')}</td>${moneyCell(tx.total)}${moneyCell(cgst)}${moneyCell(sgst)}${moneyCell(input)}${moneyCell(net)}</tr>`).join('');
