function saleGrossProfit(tx){
  return transactionItems.filter(line=>line.transaction_id===tx.id).reduce((sum,line)=>{
    const qty=Math.max(0,Number(line.quantity||0)-Number(line.returned_quantity||0)),rate=Number(line.inventory_purchase_rate||0)||Number(line.mrp||0)*.60,cost=(Number(line.cost_price||0)||rate*.95*1.05)*qty;
    const sale=Number(line.item_total||line.line_total||0);
    // Gross profit deliberately uses the saved tax-inclusive sale and full cost.
    // ITC is not applied here; the net table separately deducts GST collected.
    return sum+sale-cost;
  },0);
}
