  if(!graphDataFresh){return `<div class="page-heading between"><div><p class="eyebrow">MONTHLY PERFORMANCE</p><h1>Data &amp; Graphs</h1></div><button class="secondary" id="refresh-graphs" ${graphDataLoading?'disabled':''}>${graphDataLoading?'Refreshing…':'Refresh data'}</button></div><section class="panel graph-load-state"><div class="graph-state-icon">${graphDataLoading?'◌':'!'}</div><h2>${graphDataLoading?'Getting the latest records':'Live data could not be refreshed'}</h2><p>${graphDataLoading?'Reading sales and expenses directly from the store database.':escapeHtml(graphDataError||'Check your database connection, then try again.')}</p></section>`}
