  for(const tx of sales){const key=monthKey(tx.invoice_date||tx.created_at);if(!key||key>monthId)continue;const row=getMonth(key),amount=Number(tx.total||0),gross=saleGrossProfit(tx),gst=Number(tx.tax||transactionItems.filter(line=>line.transaction_id===tx.id).reduce((total,line)=>total+Number(line.gst_amount||0),0));if(tx.sale_type==='wholesale'){row.wholesaleSales+=amount;row.wholesaleGross+=gross;row.wholesaleGst+=gst}else if(graphRetailKind(tx)==='walkmate'){row.walkSales+=amount;row.walkGross+=gross;row.walkGst+=gst}else if(graphRetailKind(tx)==='general'){row.generalSales+=amount;row.generalGross+=gross;row.generalGst+=gst}}
