  const vals=months.map(m=>series.map(item=>item.value(m))),max=Math.max(1,...vals.flat()),W=900,H=340,left=60,right=18,top=22,bottom=44,plotH=H-top-bottom,group=(W-left-right)/12,barW=Math.min(9,group*.15),bars=months.map((m,i)=>series.map((line,j)=>{const value=vals[i][j],height=value/max*plotH,x=left+i*group+group*.08+j*(barW+2),y=top+plotH-height;return `<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${barW.toFixed(1)}" height="${Math.max(1,height).toFixed(1)}" rx="3" fill="${line.color}"><title>${m.label} ${m.year} · ${line.label}: ${currency(value)}</title></rect>`}).join('')+`<text x="${(left+i*group+group/2).toFixed(1)}" y="${H-15}" text-anchor="middle">${m.label}</text>`).join(''),ticks=[0,.25,.5,.75,1].map(f=>{const y=top+plotH*(1-f);return `<line x1="${left}" x2="${W-right}" y1="${y}" y2="${y}"/><text x="${left-8}" y="${y+4}" text-anchor="end">${currencyWhole(max*f)}</text>`}).join('');
