function bindAccountantReport(){document.querySelector('#back-to-graphs')?.addEventListener('click',()=>{page='graphs';renderApp()});document.querySelector('#accountant-month')?.addEventListener('change',e=>{graphMonth=Number(e.target.value);renderApp()});document.querySelector('#accountant-year')?.addEventListener('change',e=>{graphYear=Number(e.target.value);renderApp()});document.querySelector('#print-accountant-report')?.addEventListener('click',()=>window.print());document.querySelector('#open-accountant-report')?.addEventListener('click',()=>{page='accountant-report';renderApp()})}

async function updatePurchase(){const vendor=document.querySelector('#draft-vendor').value,invoice=document.querySelector('#draft-invoice').value.trim(),date=document.querySelector('#draft-date').value,s=purchaseDraft.summary;s.gst_label='Output IGST';const audit=purchaseAudit(),items=purchaseDraft.items.map(i=>({...i,id:i.id,product_id:i.product_id,quantity:Number(i.quantity),rate:Number(i.rate),amount:Number(i.amount),calculated_amount:money(Number(i.quantity)*Number(i.rate)),rate_discount_percent:Number(i.rate_discount_percent??(Number(i.mrp)>0?(1-Number(i.rate)/Number(i.mrp))*100:0)),amount_verified:Math.abs(money(Number(i.quantity)*Number(i.rate))-Number(i.amount))<=5.0001,cost_price:Number(i.cost_price??money(Number(i.rate)*.95*1.05)),dealer_discount_percent:Number(i.dealer_discount_percent??(Number(i.mrp)>0?(1-Number(i.cost_price)/Number(i.mrp))*100:0)),purchase_discount_amount:purchaseLinePricing(i).discount,purchase_igst_amount:purchaseLinePricing(i).igst}));if(!PURCHASE_VENDORS.includes(vendor)||!invoice||!items.length||items.some(i=>!i.product_name||i.quantity<=0||i.rate<0)){toast('Check the vendor, invoice number, and each line quantity and rate.',true);return}const warnings=audit.checks.filter(check=>!check.ok),allowMismatch=warnings.length?await confirmPurchaseOverride(warnings):false;if(warnings.length&&!allowMismatch)return;try{await db('rpc/update_purchase',{method:'POST',body:JSON.stringify({p_transaction_id:purchaseEditId,p_vendor_name:vendor,p_invoice_number:invoice,p_invoice_date:date||null,p_items:items,p_summary:s,p_allow_mismatches:allowMismatch})});await loadData();purchaseDraft=null;purchaseEditId=null;page='purchases';renderApp();toast('Invoice updated. Purchase details and inventory were updated together.')}catch(error){const message=String(error.message||'');toast(message.includes('update_purchase')?'Run the updated supabase/schema.sql in Supabase SQL Editor to enable invoice editing.':message,true)}}
function confirmPurchaseDelete(transaction,lines){return confirmRetailAction(`Delete invoice ${transaction.invoice_number||transaction.reference||''}?`,`This permanently removes the vendor invoice and its matching inventory article records. If current stock has already fallen below the quantity received on this invoice, choosing “Override & delete” will still remove those article records and their remaining stock. ${lines.length} invoice line(s) will be affected.`, 'Override & delete', true,'PURCHASE HISTORY')}
async function deletePurchase(id){return deleteStoreTransaction(id)}
async function deleteStoreTransaction(id){const tx=transactions.find(row=>row.id===id);if(!tx)return;const lines=transactionItems.filter(line=>line.transaction_id===id);let title='Delete transaction?',message='This transaction will be removed permanently.',label='Delete permanently';if(tx.type==='purchase'){title=`Delete purchase ${tx.invoice_number||tx.reference||''}?`;message='The vendor invoice and corresponding inventory article records will be removed. If stock is below the billed quantity, override allows deletion and clears the remaining stock for those articles.';label='Override & delete'}else if(tx.type==='sale'){title=`Delete invoice ${tx.reference||''}?`;message=`${lines.length} invoice line(s) will be put back into inventory where applicable. The customer ledger and balance will be recalculated, including any receipt linked to this invoice.`}else if(tx.type==='payment'){title=`Delete payment ${tx.reference||''}?`;message='The receipt will be removed from the customer ledger and the customer balance will increase by the payment amount.'}else if(tx.type==='opening_balance'){title='Delete opening balance?';message='The opening debit will be removed and the customer balance recalculated.'}else if(tx.type==='stock_adjustment'){title='Delete stock adjustment?';message='The stock change will be reversed. If reversing it would take stock below zero, override will remove that article from inventory.';label='Override & delete'}if(!await confirmRetailAction(title,message,label,tx.type==='purchase'||tx.type==='stock_adjustment','TRANSACTION HISTORY'))return;const button=document.querySelector(`[data-delete-transaction="${id}"],[data-delete-purchase="${id}"],[data-delete-sale-invoice="${id}"]`);if(button){button.disabled=true;button.textContent='Deleting…'}try{await db('rpc/delete_store_transaction',{method:'POST',body:JSON.stringify({p_transaction_id:id,p_allow_stock_override:true})});await loadData();renderApp();toast(tx.type==='payment'?'Payment removed and customer balance updated.':tx.type==='sale'?'Invoice deleted; stock and customer balance updated.':tx.type==='purchase'?'Purchase invoice and corresponding inventory articles deleted.':'Transaction deleted and related records updated.')}catch(error){if(button){button.disabled=false;button.textContent=tx.type==='purchase'?'Delete invoice':tx.type==='sale'?'Delete invoice':'Delete'}const message=String(error.message||'');toast(message.includes('delete_store_transaction')?'Run supabase/migrations/20261104_transaction_deletes_and_payment_edits.sql in Supabase SQL Editor, then retry.':message,true)}}
function editCustomerPayment(id){const tx=transactions.find(row=>row.id===id&&row.type==='payment');if(!tx)return;const modal=document.createElement('dialog');modal.className='modal payment-edit-dialog';modal.innerHTML=`<form method="dialog" class="modal-card"><button type="button" class="modal-close" aria-label="Close">×</button><p class="eyebrow">CUSTOMER PAYMENT</p><h2>Edit payment</h2><p class="muted">${escapeHtml(tx.reference||'Payment')} · ${escapeHtml(customers.find(c=>c.id===tx.customer_id)?.name||tx.customer_name||'Customer')}</p><label>Amount (₹)<input name="amount" type="number" min="0.01" step="0.01" value="${Number(tx.total||tx.amount_paid||0)}" required /></label><label>Payment method<select name="payment_method" required><option value="cash" ${tx.payment_method==='cash'?'selected':''}>Cash</option><option value="online" ${tx.payment_method==='online'?'selected':''}>Online</option></select></label><label>Note<input name="notes" value="${escapeHtml(tx.notes||'')}" /></label><div class="modal-actions payment-modal-actions"><button type="button" class="text-button danger-text" data-delete-payment>Delete payment</button><span></span><button type="button" class="secondary" data-cancel>Cancel</button><button type="button" class="primary" data-save-payment>Save changes</button></div></form>`;document.body.append(modal);modal.addEventListener('close',()=>modal.remove(),{once:true});modal.showModal();const close=()=>modal.close();modal.querySelector('.modal-close').onclick=close;modal.querySelector('[data-cancel]').onclick=close;modal.querySelector('[data-delete-payment]').onclick=async()=>{modal.close();await deleteStoreTransaction(id)};modal.querySelector('[data-save-payment]').onclick=async()=>{const form=modal.querySelector('form'),amount=Number(form.elements.amount.value),method=form.elements.payment_method.value,notes=form.elements.notes.value.trim(),button=form.querySelector('[data-save-payment]');if(!Number.isFinite(amount)||amount<=0||!['cash','online'].includes(method)){toast('Enter a valid amount and payment method.',true);return}button.disabled=true;button.textContent='Saving…';try{await db('rpc/update_customer_payment',{method:'POST',body:JSON.stringify({p_transaction_id:id,p_amount:amount,p_payment_method:method,p_notes:notes||null})});modal.close();await loadData();renderApp();toast('Payment updated; customer ledger and balance recalculated.')}catch(error){button.disabled=false;button.textContent='Save changes';const message=String(error.message||'');toast(message.includes('update_customer_payment')?'Run supabase/migrations/20261104_transaction_deletes_and_payment_edits.sql in Supabase SQL Editor, then retry.':message,true)}}}
function bindPurchases(){document.querySelector('#vendor-pdf').onchange=e=>{const file=e.target.files[0],info=document.querySelector('#file-info'),extract=document.querySelector('#extract-bill');if(file){purchaseDraft=null;document.querySelector('.purchase-review')?.remove();document.querySelector('#picked-file').textContent=file.name;document.querySelector('#picked-file-size').textContent=`${(file.size/1024/1024).toFixed(2)} MB · PDF`;info.hidden=false;extract.disabled=false;setExtractionProgress(0,'Ready',false)}else{info.hidden=true;extract.disabled=true}};document.querySelector('#clear-pdf')?.addEventListener('click',()=>{document.querySelector('#vendor-pdf').value='';purchaseDraft=null;document.querySelector('.purchase-review')?.remove();document.querySelector('#file-info').hidden=true;document.querySelector('#extract-bill').disabled=true;document.querySelector('#vendor-pdf').focus()});document.querySelector('#vendor-upload').onsubmit=extractPurchase;document.querySelectorAll('[data-edit-purchase]').forEach(button=>button.onclick=()=>openPurchaseEdit(button.dataset.editPurchase));document.querySelectorAll('[data-delete-purchase]').forEach(button=>button.onclick=()=>deletePurchase(button.dataset.deletePurchase));bindPurchaseReviewHandlers()}
